#!/usr/bin/env python3
import sys, os, re, io, csv, gzip, json
import xml.etree.ElementTree as ET
from decimal import Decimal, ROUND_HALF_UP
from datetime import date, datetime, timedelta, timezone

FACT = {'kg': Decimal(1), 'g': Decimal('0.001'), 'lb': Decimal('0.45392'), 'oz': Decimal('0.02837')}
ORDER = ['central', 'south', 'east', 'river', 'north', 'west', 'harbor', 'lakeside']
COLS = {
    'east': ['id', 'type', 'shipped', 'gross', 'net', 'status', 'note'],
    'harbor': ['rec', 'ref', 'date', 'weight', 'state'],
    'lakeside': ['id', 'kind', 'booked', 'shipped', 'gross_kg', 'net_kg', 'status'],
    'river': ['t', 'ref', 'shipped', 'weight', 'status'],
    'west': ['id', 'typ', 'shipped', 'weight', 'status', 'note'],
}
DELIM = {'east': ',', 'lakeside': ',', 'harbor': '|', 'river': '\t', 'west': ';'}
MONTHS = {m: i + 1 for i, m in enumerate('jan feb mar apr may jun jul aug sep oct nov dec'.split())}
CODES = {'D': 'delivered', 'L': 'delivered_late', 'C': 'cancelled', 'R': 'returned', 'H': 'held'}
HCODES = {'DLV': 'delivered', 'DLL': 'delivered_late', 'CAN': 'cancelled', 'RET': 'returned', 'HLD': 'held'}
NUM = re.compile(r'^\s*([-+]?[\d.,]*\d|[-+]?[\d.,]*)\s*([A-Za-z]*)\s*$')


def decode(b):
    if b[:2] == b'\x1f\x8b':
        b = gzip.decompress(b)
    if b[:3] == b'\xef\xbb\xbf':
        return b[3:].decode('utf-8')
    if b[:2] in (b'\xff\xfe', b'\xfe\xff'):
        return b.decode('utf-16')
    head = b[:1000].decode('latin-1')
    m = re.search(r'(?im)^#\s*charset\s*:\s*([\w.-]+)', head)
    enc = m.group(1) if m else 'utf-8'
    return b.decode(enc)


def norm_id(s):
    m = re.search(r'(?i)SH\D*?(\d+)', s or '')
    return int(m.group(1)) if m else None


def norm_status(s):
    return re.sub(r'[\s\-]+', '_', (s or '').strip().lower())


def parse_date(s, form):
    s = (s or '').strip()
    f = (form or '').strip()
    fl = f.lower()
    if not s:
        return None
    if fl == 'serial' or (fl == '' and re.fullmatch(r'\d{5}', s)):
        return date(1899, 12, 30) + timedelta(days=int(float(s)))
    m = re.fullmatch(r'(\d{1,2}) ([A-Za-z]{3})[a-z]* (\d{4})', s)
    if m:
        return date(int(m.group(3)), MONTHS[m.group(2).lower()], int(m.group(1)))
    m = re.fullmatch(r'(\d{4})-(\d{2})-(\d{2})', s)
    if m:
        return date(*map(int, m.groups()))
    m = re.fullmatch(r'(\d{4})(\d{2})(\d{2})', s)
    if m:
        return date(*map(int, m.groups()))
    m = re.fullmatch(r'(\d{4})(\d{3})', s)
    if m:
        return date(int(m.group(1)), 1, 1) + timedelta(days=int(m.group(2)) - 1)
    m = re.fullmatch(r'(\d{1,2})[-/.](\d{1,2})[-/.](\d{4})', s)
    if m:
        a, b, y = map(int, m.groups())
        if fl in ('mm/dd/yyyy', 'mdy'):
            return date(y, a, b)
        return date(y, b, a)  # DMY, DD/MM/YYYY, DD.MM.YYYY
    m = re.fullmatch(r'(\d{4})[/.](\d{1,2})[/.](\d{1,2})', s)
    if m:
        return date(*map(int, m.groups()))
    raise ValueError('bad date %r' % s)


def parse_time(s):
    s = s.strip()
    if s.endswith(('Z', 'z')):
        s = s[:-1] + '+00:00'
    dt = datetime.fromisoformat(s)
    if dt.tzinfo is not None:
        dt = dt.astimezone(timezone.utc)
    return dt.date()


def to_kg(val, unit, decimal_comma=False):
    """val: string possibly with unit suffix."""
    if isinstance(val, (int, float)):
        d = Decimal(str(val)); u = unit
    else:
        m = NUM.match(val)
        if not m:
            raise ValueError('bad weight %r' % val)
        t, u2 = m.group(1), m.group(2).lower()
        if u2 in FACT:
            unit = u2
        if decimal_comma:
            t = t.replace('.', '').replace(',', '.')
        else:
            t = t.replace(',', '')
        d = Decimal(t)
        u = unit
    return d * FACT[u]


def rec(type_, num, status=None, kg=None, day=None):
    return {'type': type_, 'num': num, 'status': status, 'kg': kg, 'day': day}


def first_word_unit(v):
    w = v.strip().split()
    return w[0].lower() if w else None


def parse_delimited(depot, text):
    cols = COLS[depot]
    colset = set(cols)
    delim = DELIM[depot]
    if delim == ',':
        rows = csv.reader(io.StringIO(text, newline=''), delimiter=',')
    else:
        rows = (l.rstrip('\r').split(delim) for l in text.split('\n'))
    seq = None
    dirs = {}
    header = None
    out = []
    base_unit = {'east': 'kg', 'river': 'kg', 'west': 'kg', 'harbor': 'kg', 'lakeside': 'kg'}[depot]
    base_date = {'east': 'YMD', 'harbor': 'iso', 'lakeside': 'iso', 'river': 'MM/DD/YYYY', 'west': 'DD.MM.YYYY'}[depot]
    for r in rows:
        if not r or (len(r) == 1 and not r[0].strip()):
            continue
        if r[0].startswith('#'):
            line = delim.join(r)
            m = re.match(r'#\s*([^:=]+?)\s*:\s*(.*)$', line)
            if m:
                dirs[m.group(1).strip().lower()] = m.group(2).strip()
            m = re.search(r'seq\s*=\s*(\d+)', line)
            if m:
                seq = int(m.group(1))
            continue
        if all(f.strip() in colset for f in r):
            header = [f.strip() for f in r]
            continue
        if header is None:
            continue
        g = lambda k: (r[header.index(k)] if k in header and header.index(k) < len(r) else '')
        # weight unit carried by the row
        rowunit = None
        if len(r) > len(header):
            for i, f in enumerate(r):
                if f.strip().lower() in FACT:
                    rowunit = f.strip().lower()
                    r = r[:i] + r[i + 1:]
                    break
        idk = 'ref' if depot in ('harbor', 'river') else 'id'
        num = norm_id(g(idk))
        if num is None:
            continue
        tk = {'east': 'type', 'harbor': 'rec', 'lakeside': 'kind', 'river': 't', 'west': 'typ'}[depot]
        t = g(tk).strip().upper()
        typ = 'void' if t in ('V', 'VOID') else 'correction' if t in ('C', 'COR', 'CORR') else 'new'
        if typ == 'void':
            out.append(rec('void', num))
            continue
        wk = {'east': 'gross', 'harbor': 'weight', 'lakeside': 'gross_kg', 'river': 'weight', 'west': 'weight'}[depot]
        unit = base_unit
        du = dirs.get('unit') or dirs.get('weight unit')
        if du:
            unit = first_word_unit(du)
        if rowunit:
            unit = rowunit
        if depot == 'lakeside':
            unit = 'kg'
        form = dirs.get('dates') or dirs.get('date format') or base_date
        dk = {'east': 'shipped', 'harbor': 'date', 'lakeside': 'shipped', 'river': 'shipped', 'west': 'shipped'}[depot]
        kg = to_kg(g(wk), unit, decimal_comma=(depot == 'west'))
        day = parse_date(g(dk), form)
        st = g('state') if depot == 'harbor' else g('status')
        st = HCODES.get(st.strip().upper(), norm_status(st)) if depot == 'harbor' else norm_status(st)
        out.append(rec(typ, num, st, kg, day))
    return seq, out


def parse_fixed(text):
    layouts = {
        'FW1': (42, dict(id=(0, 9), type=(9, 10), shipped=(10, 17), weight=(17, 25), status=(25, 26)), 'g', 'ord'),
        'FW2': (43, dict(type=(0, 1), id=(1, 10), shipped=(10, 18), weight=(18, 26), status=(26, 27)), 'cg', 'ymd'),
        'FW3': (41, dict(id=(0, 9), shipped=(9, 16), type=(16, 17), weight=(17, 24), status=(24, 25)), 'dlb', 'ord'),
    }
    bylen = {v[0]: k for k, v in layouts.items()}
    cur = None
    seq = None
    out = []
    for line in text.split('\n'):
        line = line.rstrip('\r')
        if '\f' in line or line.startswith('SOUTH DEPOT'):
            continue
        if line.startswith('#LAYOUT'):
            cur = line.split()[1].strip()
            continue
        if line.startswith('#SEQ'):
            seq = int(line.split()[1])
            continue
        if line.startswith('#') or not line.strip():
            continue
        name = bylen.get(len(line))
        if name is None:
            name = cur
            if name is None:
                continue
            line = line.ljust(layouts[name][0])[:layouts[name][0]]
        L = layouts[name][1]
        f = {k: line[a:b] for k, (a, b) in L.items()}
        num = norm_id(f['id'])
        if num is None:
            continue
        t = f['type'].strip().upper()
        if t == 'V':
            out.append(rec('void', num))
            continue
        typ = 'correction' if t == 'C' else 'new'
        w = Decimal(int(f['weight']))
        if name == 'FW1':
            kg = w * FACT['g']
        elif name == 'FW2':
            kg = w / 100
        else:
            kg = w / 10 * FACT['lb']
        s = f['shipped'].strip()
        day = parse_date(s, '')
        out.append(rec(typ, num, CODES.get(f['status'].strip().upper(), '?'), kg, day))
    return seq, out


def parse_xml(text):
    text = re.sub(r'^\s*<\?xml[^>]*\?>', '', text)
    root = ET.fromstring(text)
    seq = int(root.get('seq'))
    ru = (root.get('weight-unit') or 'kg').strip().lower()
    out = []
    for sh in root.iter('shipment'):
        num = norm_id(sh.get('id'))
        if num is None:
            continue
        t = (sh.get('type') or 'new').strip().lower()
        if t == 'void':
            out.append(rec('void', num))
            continue
        typ = 'correction' if t.startswith('corr') else 'new'
        w = sh.find('weight')
        unit = (w.get('unit') or ru).strip().lower()
        kg = to_kg(w.text.strip(), unit)
        sc = sh.find('shipped')
        if sc is not None:
            day = parse_time(sc.text)
        else:
            day = parse_date(sh.get('shipped'), '')
        out.append(rec(typ, num, norm_status(sh.findtext('status')), kg, day))
    return seq, out


def parse_json(text):
    seq = None
    out = []
    for line in text.split('\n'):
        line = line.strip()
        if not line:
            continue
        v = json.loads(line)
        objs = v if isinstance(v, list) else [v]
        for o in objs:
            if not isinstance(o, dict):
                continue
            if 'meta' in o and isinstance(o['meta'], dict):
                if 'seq' in o['meta']:
                    seq = int(o['meta']['seq'])
                continue
            num = norm_id(str(o.get('id', '')))
            if num is None:
                continue
            k = (o.get('kind') or 'new').lower()
            if k == 'void':
                out.append(rec('void', num))
                continue
            typ = 'correction' if k in ('amend', 'correction') else 'new'
            kg = None
            for key, val in o.items():
                m = re.fullmatch(r'weight_(kg|g|lb|oz)', key)
                if m:
                    kg = to_kg(val if isinstance(val, str) else Decimal(repr(val)) if isinstance(val, float) else val, m.group(1)) \
                        if not isinstance(val, float) else Decimal(repr(val)) * FACT[m.group(1)]
            out.append(rec(typ, num, norm_status(o.get('status')), kg, parse_time(o['shipped_at'])))
    return seq, out


def parse_file(depot, path):
    text = decode(open(path, 'rb').read())
    if text.startswith('\ufeff'):
        text = text[1:]
    if depot == 'central':
        return parse_xml(text)
    if depot == 'north':
        return parse_json(text)
    if depot == 'south':
        return parse_fixed(text)
    return parse_delimited(depot, text)


def main():
    data, outf = sys.argv[1], sys.argv[2]
    exports = {}
    for name in sorted(os.listdir(data)):
        p = os.path.join(data, name)
        if not os.path.isfile(p):
            continue
        depot = name.split('-')[0]
        seq, recs = parse_file(depot, p)
        exports.setdefault(depot, []).append((seq if seq is not None else 0, name, recs))
    corrections = resends = 0
    current = {}
    for depot, lst in exports.items():
        cur = {}
        lst.sort(key=lambda x: (x[0], x[1]))
        for _, _, recs in lst:
            for r in recs:
                n = r['num']
                if r['type'] == 'new':
                    if n in cur:
                        resends += 1
                    else:
                        cur[n] = r
                elif r['type'] == 'correction':
                    cur[n] = r
                    corrections += 1
                else:
                    cur.pop(n, None)
                    corrections += 1
        current[depot] = cur
    depots = {d: [0, Decimal(0)] for d in exports}
    months = {}
    owners = {}
    for d in current:
        for n in current[d]:
            owners.setdefault(n, []).append(d)
    handovers = 0
    rank = {d: i for i, d in enumerate(ORDER)}
    for n, ds in owners.items():
        if len(ds) > 1:
            handovers += 1
        d = min(ds, key=lambda x: rank.get(x, 99))
        r = current[d][n]
        if r['status'] in ('delivered', 'delivered_late'):
            depots[d][0] += 1
            depots[d][1] += r['kg']
            m = '%04d-%02d' % (r['day'].year, r['day'].month)
            e = months.setdefault(m, [0, Decimal(0)])
            e[0] += 1
            e[1] += r['kg']
    q = lambda x: float(x.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP))
    res = {
        'depots': {d: {'shipments': depots[d][0], 'total_kg': q(depots[d][1])} for d in sorted(depots)},
        'months': {m: {'shipments': months[m][0], 'total_kg': q(months[m][1])} for m in sorted(months)},
        'corrections_applied': corrections,
        'resends_dropped': resends,
        'handovers': handovers,
    }
    with open(outf, 'w') as f:
        json.dump(res, f, indent=2)


main()
